const nonneg=v=>Number.isSafeInteger(v)&&v>=0;
class Orders {
  constructor(stock,prices={}) { this.stock={...stock};this.prices={...prices};this.rows={};this.applied={}; }
  reserve(id,sku,qty,now=0,ttl=10) {
    if(!Number.isSafeInteger(qty)||qty<=0) throw new RangeError('qty');
    if(!Number.isSafeInteger(ttl)||ttl<=0) throw new RangeError('ttl');
    if(!nonneg(now)) throw new RangeError('now');
    if(!Number.isSafeInteger(now+ttl)) throw new RangeError('deadline');
    this.expire(now);
    const r=this.rows[id];
    if(r) return !r.expired&&r.sku===sku&&r.qty===qty;
    if((this.stock[sku]||0)<qty) return false;
    this.stock[sku]=(this.stock[sku]||0)-qty;
    this.rows[id]={sku,qty,deadline:now+ttl,expired:false,done:0,refunded:0};return true;
  }
  expire(now) {
    if(!nonneg(now)) throw new RangeError('now');
    for(const r of Object.values(this.rows)) {
      if(!r.expired&&r.deadline<=now) {r.expired=true;this.stock[r.sku]=(this.stock[r.sku]||0)+r.qty-r.done;}
    }
  }
  _cents(r,qty) {return BigInt(this.prices[r.sku]??0)*BigInt(qty);}
  fulfill(id,qty,now=0) {
    if(!Number.isSafeInteger(qty)||qty<=0) throw new RangeError('qty');
    if(!nonneg(now)) throw new RangeError('now');
    this.expire(now);
    const r=this.rows[id];
    if(!r||r.expired||qty>r.qty-r.done) return null;
    r.done+=qty;return this._cents(r,qty);
  }
  refund(id,qty) {
    if(!Number.isSafeInteger(qty)||qty<=0) throw new RangeError('qty');
    const r=this.rows[id];
    if(!r||qty>r.done-r.refunded) return null;
    r.refunded+=qty;this.stock[r.sku]=(this.stock[r.sku]||0)+qty;return this._cents(r,qty);
  }
  dumps() {
    const prices={};
    for(const k of Object.keys(this.prices)) prices[k]=String(this.prices[k]);
    return JSON.stringify({version:2,stock:this.stock,prices,rows:this.rows,replay:this.applied});
  }
  static loads(text) {
    let d;
    try {d=JSON.parse(text);} catch(e) {throw new RangeError('malformed');}
    const isObj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
    if(!isObj(d)) throw new RangeError('snapshot');
    if(d.version!==2) throw new RangeError('version');
    if(!isObj(d.stock)||!isObj(d.prices)||!isObj(d.rows)) throw new RangeError('fields');
    for(const v of Object.values(d.stock)) if(!nonneg(v)) throw new RangeError('stock');
    for(const v of Object.values(d.prices)) if(typeof v!=='string'||!/^\d+$/.test(v)) throw new RangeError('price');
    const replay=d.replay===undefined?{}:d.replay;
    if(!isObj(replay)) throw new RangeError('replay');
    const rows={};
    for(const [id,r] of Object.entries(d.rows)) {
      if(!isObj(r)||typeof r.sku!=='string'||typeof r.expired!=='boolean') throw new RangeError('row');
      if(!Number.isSafeInteger(r.qty)||r.qty<=0||!nonneg(r.deadline)||!nonneg(r.done)||!nonneg(r.refunded)) throw new RangeError('row');
      if(r.done>r.qty||r.refunded>r.done) throw new RangeError('row');
      rows[id]={sku:r.sku,qty:r.qty,deadline:r.deadline,expired:r.expired,done:r.done,refunded:r.refunded};
    }
    const o=new Orders(d.stock,d.prices);
    o.rows=rows;o.applied=JSON.parse(JSON.stringify(replay));
    return o;
  }
  available(sku,now) {
    if(now!==undefined) this.expire(now);
    return this.stock[sku]||0;
  }
}
module.exports={Orders};
